mapper.select:
SELECT md.year AS DATA_YEAR , md.month AS DATA_MONTH , SUM(md.usage_kwh) AS TOTAL_KWH , AVG(md.usage_kwh) AS AVG_KWH FROM monthly_data md JOIN region rg ON rg.region_id = md.region_id
WHERE rg.region_name = #{regionName}
GROUP BY md.year, md.month ORDER BY md.year DESC, md.month DESC LIMIT 1

SELECT md.year AS DATA_YEAR , md.month AS DATA_MONTH , SUM(md.usage_kwh) AS TOTAL_KWH , AVG(md.usage_kwh) AS AVG_KWH FROM monthly_data md JOIN region rg ON rg.region_id = md.region_id
WHERE rg.region_name = #{regionName}
GROUP BY md.year, md.month ORDER BY md.year, md.month

SELECT fc.year AS DATA_YEAR , fc.month AS DATA_MONTH , SUM(fc.predicted_kwh) AS TOTAL_KWH , AVG(fc.predicted_kwh) AS AVG_KWH , SUM(fc.prev_year_kwh) AS PREV_TOTAL_KWH , AVG(fc.prev_year_kwh) AS PREV_AVG_KWH , ROUND((SUM(fc.predicted_kwh) / SUM(fc.prev_year_kwh) - 1) * 100, 1) AS YOY_PCT FROM forecast fc JOIN region rg ON rg.region_id = fc.region_id
WHERE rg.region_name = #{regionName}
GROUP BY fc.year, fc.month ORDER BY fc.year, fc.month
